import crypto from 'node:crypto';

export function seal(key: Buffer, plain: string): string {
  const c = crypto.createCipheriv('aes-256-ecb', key, null);
  return Buffer.concat([c.update(plain, 'utf8'), c.final()]).toString('base64url');
}

export function unseal(key: Buffer, token: string): string {
  const d = crypto.createDecipheriv('aes-256-ecb', key, null);
  const buf = Buffer.from(token, 'base64url');
  return Buffer.concat([d.update(buf), d.final()]).toString('utf8');
}

