pub enum HexError { OddLength, InvalidDigit }

pub fn decode_hex(s: &str) -> Result<Vec<u8>, HexError> {
    s.as_bytes()
        .chunks_exact(2)
        .map(|pair| {
            let s2 = std::str::from_utf8(pair).map_err(|_| HexError::InvalidDigit)?;
            u8::from_str_radix(s2, 16).map_err(|_| HexError::InvalidDigit)
