export function decryptBlob(key: Buffer, packed: Buffer): Buffer {
  if (packed.length < 28) throw new Error('truncated ciphertext');
  const d = crypto.createDecipheriv('aes-256-gcm', key, packed.subarray(0, 12));
  d.setAuthTag(packed.subarray(12, 28));
  return Buffer.concat([d.update(packed.subarray(28)), d.final()]);
}"}

