pub enum VarintError { Truncated, Overflow }

pub fn decode_u64(buf: &[u8]) -> Result<u64, VarintError> {
    let mut out = 0u64;
    let mut shift = 0u32;
    for &b in buf {
        out |= u64::from(b & 0x7f) << shift;
        if b & 0x80 == 0 {
            return Ok(out);
        }
        shift += 7;
    }
    Err(VarintError::Truncated)
}

