struct Key32;
impl KeyType for Key32 { fn len(&self) -> usize { 32 } }

pub fn derive_aead_key(raw_ecdh: &[u8; 32], salt: &[u8], info: &[u8]) -> Result<[u8; 32], ring::error::Unspecified> {
    let prk = Salt::new(HKDF_SHA256, salt).extract(raw_ecdh);
    let okm = prk.expand(&[info], Key32)?;
    let mut out = [0u8; 32];
    okm.fill(&mut out)?;
    Ok(out)
}"}

