#include <stddef.h>
#include <stdint.h>

uint16_t crc16_ccitt(const uint8_t *buf, size_t len) {
    uint16_t crc;
    for (size_t i = 0; i < len; i++) {
        crc ^= (uint16_t)buf[i] << 8;
        for (int b = 0; b < 8; b++) {
            crc = (crc & 0x8000) ? (uint16_t)((crc << 1) ^ 0x1021) : (uint16_t)(crc << 1);
        }
    }
    return crc;
}

