from cryptography.hazmat.primitives.ciphers.aead import AESGCM

def seal_adapter(key: bytes, adapter_id: str, raw_weights: bytes) -> bytes:
    nonce = os.urandom(12)
    aad = adapter_id.encode("utf-8")
    return nonce + AESGCM(key).encrypt(nonce, raw_weights, aad)

def unseal_adapter(key: bytes, adapter_id: str, blob: bytes) -> bytes:
    if len(blob) < 28:
        raise ValueError("Truncated AES-GCM blob")
    aad = adapter_id.encode("utf-8")
    return AESGCM(key).decrypt(blob[:12], blob[12:], aad)"}

