	"compress/gzip"
	"errors"
	"io"
)

const maxGunzipBytes = 4 << 20

func GunzipPayload(r io.Reader) ([]byte, error) {
	zr, err := gzip.NewReader(r)
	if err != nil {
		return nil, err
	}
	defer zr.Close()
	out, err := io.ReadAll(io.LimitReader(zr, maxGunzipBytes+1))
	if err != nil {
		return nil, err
	}
	if len(out) > maxGunzipBytes {
		return nil, errors.New("decompressed payload exceeds 4 MiB")
	}
	return out, nil
}"}

